ALTER TABLE business_account_applications ADD COLUMN business_details_json MEDIUMTEXT NULL;
CREATE TABLE account_consents(account_id BIGINT UNSIGNED NOT NULL,consent_version VARCHAR(64) NOT NULL,accepted_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(account_id,consent_version),CONSTRAINT account_consents_account_fk FOREIGN KEY(account_id) REFERENCES accounts(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE business_application_images(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,application_id BIGINT UNSIGNED NOT NULL,storage_name VARCHAR(100) NOT NULL UNIQUE,original_name VARCHAR(255) NOT NULL,mime_type VARCHAR(32) NOT NULL,file_size INT UNSIGNED NOT NULL,width SMALLINT UNSIGNED NOT NULL,height SMALLINT UNSIGNED NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT business_application_images_application_fk FOREIGN KEY(application_id) REFERENCES business_account_applications(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
